import { type ConfirmOptions, type ConfirmResult, uiApi } from '@weavix/sdk-core';
import { useCallback } from 'react';

export type UseConfirmReturn = {
    show: (options: ConfirmOptions) => Promise<ConfirmResult>;
};

const useConfirmImpl = () => {
    const show = useCallback((options: ConfirmOptions) => uiApi.confirm.show(options), []);

    return { show };
};

export const useConfirm = useConfirmImpl as () => UseConfirmReturn;
