import {
    type BasicContext,
    type ContextLevel,
    type Theme,
    dispatchHostEvent,
    hostApi,
    setHandler,
    uiApi,
} from '@weavix/sdk-core';
import {
    type ReactNode,
    createContext,
    useContext,
    useEffect,
    useMemo,
    useRef,
    useState,
} from 'react';
import { useContext as useSlotContext } from '../hooks/useContext';
import { useIsYateam } from '../hooks/useIsYateam';
import { useLanguage } from '../hooks/useLanguage';
import { useOrgId } from '../hooks/useOrgId';
import { useTheme } from '../hooks/useTheme';
import { useUserId } from '../hooks/useUserId';
import { ErrorBoundary } from './ErrorBoundary';
import { PluginError } from './PluginError';
import { useIsOrbita } from '../hooks/useIsOrbita';

/**
 * Generic registerHandler — no Tracker-specific types.
 */
export type RegisterHandlerFunction = (
    methodName: string,
    handler: (...args: unknown[]) => unknown,
) => void;

interface CommonPluginContextValue {
    /** Current host theme. Updated reactively on theme.changed. */
    theme: Theme | undefined;
    /** Current host language. Updated reactively on language.changed. */
    language: string | undefined;
    /** Service in which the plugin was opened. */
    service: string;
    /** User ID. */
    userId?: string;
    /** Organization ID. */
    orgId?: string;
    /** Is this a yateam environment? */
    isYateam?: boolean;
    /** Is the Orbit enabled */
    isOrbita?: boolean;
    /** Origin of the parent window (host). */
    origin: string;
    /** Slot in which the plugin is opened. */
    slot: string;
    /** URL inside the plugin. */
    innerUrl: string;
    /** Plugin query parameters. */
    queryParams: Record<string, string>;
    /** Register a handler for responding to host requests. */
    registerHandler: RegisterHandlerFunction;
}

/**
 * Plugin context at contextLevel = 'basic'.
 * slotContext contains only entityId.
 */
export interface BasicPluginContextValue extends CommonPluginContextValue {
    /** Page context — only entityId at basic level. */
    slotContext: BasicContext | undefined;

    /** Context level declared in the manifest. */
    contextLevel: 'basic';
}

/**
 * Plugin context at contextLevel = 'full'.
 * slotContext contains the full slot object.
 */
export interface FullPluginContextValue extends CommonPluginContextValue {
    /** Page context — full slot object at full level. */
    slotContext: unknown;

    /** Context level declared in the manifest. */
    contextLevel: 'full';
}

export type PluginContextValue = BasicPluginContextValue | FullPluginContextValue;

/** Internal context type — only stable data (slot + registerHandler) */
type InternalContextValue = {
    slot: string;
    registerHandler: RegisterHandlerFunction;
    innerUrl: string;
    queryParams: Record<string, string>;
    contextLevel: ContextLevel;
    entityId: string | null;
    entityMeta: Record<string, string> | undefined;
};

const PluginContext = createContext<InternalContextValue | null>(null);

/**
 * Hook for getting theme, language, slot and slot context from PluginProvider.
 *
 * All values are reactive — updated automatically on push events from the host:
 * - `theme` — on `theme.changed`
 * - `language` — on `language.changed`
 * - `slotContext` — on `context.changed`
 * - `isOrbita` — on `isOrbita.changed`
 *
 * Supports two context levels:
 * - `'basic'` (default) — slotContext contains only `{ entityId }`.
 * - `'full'` — slotContext contains the full slot object.
 * Requires `contextLevel: "full"` in the plugin manifest.
 */
export function usePluginContext(): BasicPluginContextValue;
export function usePluginContext(level: 'basic'): BasicPluginContextValue;
export function usePluginContext(level: 'full'): FullPluginContextValue;
export function usePluginContext(
    level: ContextLevel = 'basic',
): BasicPluginContextValue | FullPluginContextValue {
    const ctx = useContext(PluginContext);
    if (!ctx) {
        throw new Error('usePluginContext must be used within PluginProvider');
    }

    // Runtime guard: code requests more than manifest allows
    if (level === 'full' && ctx.contextLevel !== 'full') {
        throw new Error(
            "🛑 [Security] Code requests 'full' context, but manifest declares 'basic'. " +
                'Change the contextLevel in your manifest to get full access.',
        );
    }

    // Reactive values — each hook subscribes to its own event
    const theme = useTheme();
    const language = useLanguage();
    const isYateam = useIsYateam();
    const userId = useUserId();
    const orgId = useOrgId();
    const fullSlotContext = useSlotContext();
    const isOrbita = useIsOrbita();

    const commonContextValue = {
        service: hostApi.getService(),
        origin: hostApi.getOrigin(),
        slot: ctx.slot,
        innerUrl: ctx.innerUrl,
        queryParams: ctx.queryParams,
        registerHandler: ctx.registerHandler,
        theme,
        language,
        isYateam,
        userId,
        orgId,
        isOrbita,
    };

    if (level === 'basic') {
        const basicSlotContext: BasicContext | undefined = ctx.entityId
            ? { entityId: ctx.entityId, ...(ctx.entityMeta ? { entityMeta: ctx.entityMeta } : {}) }
            : undefined;

        return {
            ...commonContextValue,
            contextLevel: 'basic',
            slotContext: basicSlotContext,
        } as BasicPluginContextValue;
    }

    return {
        ...commonContextValue,
        contextLevel: 'full',
        slotContext: fullSlotContext,
    } as FullPluginContextValue;
}

export interface PluginProviderProps {
    children: ReactNode;
    /**
     * Automatically resize the plugin container when content changes.
     * @default true
     */
    autoResize?: boolean;
    /**
     * Component to display during initialization.
     * @default undefined (nothing shown)
     */
    fallback?: ReactNode;
    /**
     * Component to display on initialization error.
     * @default <PluginError error={error} />
     */
    errorFallback?: (error: Error) => ReactNode;
    /**
     * Automatically notify the host that the plugin is ready after initialization.
     * @default true
     */
    autoNotifyReady?: boolean;
}

export const isInternalUrl = (url: string) => {
    try {
        const urlObj = new URL(url, window.location.href);
        return urlObj.origin === window.location.origin;
    } catch {
        return true;
    }
};

/**
 * Generic plugin provider.
 * Wraps the application and manages the plugin lifecycle.
 *
 * After initialization, theme, language and slot context are available via
 * `usePluginContext()` and update reactively on push events from the host.
 * @example
 * ```tsx
 * root.render(
 *   <PluginProvider>
 *     <App />
 *   </PluginProvider>
 * );
 * ```
 */
export function PluginProvider({
    children,
    autoResize = true,
    fallback,
    errorFallback,
    autoNotifyReady = true,
}: PluginProviderProps) {
    const initializedRef = useRef(false);
    const [initialized, setInitialized] = useState(false);
    const [error, setError] = useState<Error | null>(null);
    const [internalValue, setInternalValue] = useState<InternalContextValue | null>(null);

    const registerHandler = useMemo<RegisterHandlerFunction>(() => {
        return (methodName: string, handler: (...args: unknown[]) => unknown) =>
            setHandler(methodName as never, handler as never);
    }, []);

    useEffect(() => {
        const handleLinkClick = (event: MouseEvent) => {
            const target = event.target as HTMLElement;
            const linkElement = target.closest<HTMLElement>('[href], [data-href]');

            if (!linkElement) return;

            const href = linkElement.getAttribute('href') || linkElement.getAttribute('data-href');
            if (!href) return;

            if (isInternalUrl(href)) {
                return;
            }

            event.preventDefault();

            const targetAttr = linkElement.getAttribute('target');
            const newTab = targetAttr === '_blank';

            uiApi
                .navigate({
                    path: href,
                    options: {
                        newTab,
                    },
                })
                .then(() => {
                    console.info(`Navigation: ${href}`);
                })
                .catch((err) => {
                    console.error('Navigation error:', err);
                });
        };

        document.addEventListener('click', handleLinkClick);

        return () => {
            document.removeEventListener('click', handleLinkClick);
        };
    }, []);

    useEffect(() => {
        // Prevent double initialization in React StrictMode
        if (initializedRef.current) {
            return;
        }

        const initPlugin = async () => {
            try {
                hostApi.init({ autoResize });
                initializedRef.current = true;

                const contextLevel = hostApi.getContextLevel();
                const entityId = hostApi.getEntityId();
                const entityMeta = hostApi.getEntityMeta();

                setInternalValue({
                    slot: hostApi.getSlot(),
                    innerUrl: hostApi.getInnerUrl(),
                    queryParams: hostApi.getQueryParams(),
                    contextLevel,
                    entityId,
                    entityMeta,
                    registerHandler,
                });

                if (autoNotifyReady) {
                    await hostApi.notifyReady();
                }

                // Fetch initial values and prime the eventBus cache so that
                // hooks subscribing after these responses arrive still get the values.
                // For basic contextLevel, skip the context.get postMessage call.
                const [theme, language, context, isYateam, userId, orgId, isOrbita] =
                    await Promise.allSettled([
                        hostApi.getTheme(),
                        hostApi.getLanguage(),
                        contextLevel === 'full' ? hostApi.getContext() : Promise.resolve(null),
                        hostApi.getIsYateam(),
                        hostApi.getUserId(),
                        hostApi.getOrgId(),
                        hostApi.getIsOrbita(),
                    ]);

                if (theme.status === 'fulfilled' && theme.value) {
                    dispatchHostEvent({
                        messageId: '',
                        type: 'event',
                        method: 'theme.changed',
                        result: theme.value,
                    });
                }
                if (language.status === 'fulfilled' && language.value) {
                    dispatchHostEvent({
                        messageId: '',
                        type: 'event',
                        method: 'language.changed',
                        result: language.value,
                    });
                }

                if (isYateam.status === 'fulfilled' && isYateam.value) {
                    dispatchHostEvent({
                        messageId: '',
                        type: 'event',
                        method: 'isYateam.changed',
                        result: isYateam.value,
                    });
                }

                if (isOrbita.status === 'fulfilled') {
                    dispatchHostEvent({
                        messageId: '',
                        type: 'event',
                        method: 'isOrbita.changed',
                        result: isOrbita.value,
                    });
                }

                if (userId.status === 'fulfilled' && userId.value) {
                    dispatchHostEvent({
                        messageId: '',
                        type: 'event',
                        method: 'userId.changed',
                        result: userId.value,
                    });
                }

                if (orgId.status === 'fulfilled' && orgId.value) {
                    dispatchHostEvent({
                        messageId: '',
                        type: 'event',
                        method: 'orgId.changed',
                        result: orgId.value,
                    });
                }

                // For basic level, dispatch entityId as context.
                // For full level, dispatch the full context from host.
                if (contextLevel === 'basic') {
                    if (entityId) {
                        dispatchHostEvent({
                            messageId: '',
                            type: 'event',
                            method: 'context.changed',
                            result: { entityId, ...(entityMeta ? { entityMeta } : {}) },
                        });
                    }
                } else if (context.status === 'fulfilled' && context.value) {
                    dispatchHostEvent({
                        messageId: '',
                        type: 'event',
                        method: 'context.changed',
                        result: context.value,
                    });
                }

                setInitialized(true);
            } catch (err) {
                setError(err as Error);
            }
        };

        initPlugin();
    }, [autoResize, registerHandler, autoNotifyReady]);

    if (error) {
        if (errorFallback) {
            return <>{errorFallback(error)}</>;
        }

        return <PluginError error={error} />;
    }

    if (!initialized || !internalValue) {
        return <>{fallback}</>;
    }

    return (
        <ErrorBoundary
            fallback={errorFallback || ((pluginError) => <PluginError error={pluginError} />)}
        >
            <PluginContext.Provider value={internalValue}>{children}</PluginContext.Provider>
        </ErrorBoundary>
    );
}
