import { type LocalizedString, getLocalizedString } from '@weavix/sdk-core';
import { useLanguage } from './useLanguage';

const useLocalizedStringImpl = (fallbackLanguage = 'ru') => {
    const language = useLanguage();

    return (value: LocalizedString): string => {
        return getLocalizedString(value, language, fallbackLanguage);
    };
};

/**
 * Хук для получения локализованной строки на основе текущего языка из контекста.
 */
export const useLocalizedString = useLocalizedStringImpl as (
    fallbackLanguage?: string,
) => (value: LocalizedString) => string;
