import {
    HostApi,
    type HostInitOptions,
    type Theme,
    type Unsubscribe,
    dispatchHostEvent,
    on,
} from '@weavix/sdk-core';
import { useEffect, useRef, useState } from 'react';

export type PluginBootstrapState<TContext> = {
    host: HostApi<TContext>;
    loading: boolean;
    error: string | null;
    theme?: Theme;
    language?: string;
    context?: TContext;
    userId?: string;
    orgId?: string;
    isYateam?: boolean;
    isOrbita?: boolean;
};

function getErrorMessage(error: unknown): string {
    return error instanceof Error ? error.message : 'Unknown plugin bootstrap error';
}

type BootstrapEventMethod = Parameters<typeof dispatchHostEvent>[0]['method'];

function dispatchInitialValue(method: BootstrapEventMethod, result: unknown) {
    if (result === undefined || result === null) {
        return;
    }

    dispatchHostEvent({
        messageId: '',
        type: 'event',
        method,
        result,
    });
}

export function usePluginBootstrap<TContext>(
    options: HostInitOptions = {},
): PluginBootstrapState<TContext> {
    const { autoResize = true } = options;
    const hostRef = useRef<HostApi<TContext> | null>(null);

    if (!hostRef.current) {
        hostRef.current = new HostApi<TContext>();
    }

    const host = hostRef.current;
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [theme, setTheme] = useState<Theme>();
    const [language, setLanguage] = useState<string>();
    const [context, setContext] = useState<TContext>();
    const [userId, setUserId] = useState<string>();
    const [orgId, setOrgId] = useState<string>();
    const [isYateam, setIsYateam] = useState<boolean>();
    const [isOrbita, setIsOrbita] = useState<boolean>();

    useEffect(() => {
        let cancelled = false;
        const unsubscribes: Unsubscribe[] = [];

        const subscribe = <M extends Parameters<typeof on>[0]>(
            method: M,
            callback: (value: unknown) => void,
        ) => {
            unsubscribes.push(on(method, callback as never));
        };

        try {
            host.init({ autoResize });

            subscribe('context.changed', (value) => setContext(value as TContext));
            subscribe('theme.changed', (value) => setTheme(value as Theme));
            subscribe('language.changed', (value) => setLanguage(value as string));
            subscribe('userId.changed', (value) => setUserId(value as string));
            subscribe('orgId.changed', (value) => setOrgId(value as string));
            subscribe('isYateam.changed', (value) => setIsYateam(value as boolean));
            subscribe('isOrbita.changed', (value) => setIsOrbita(value as boolean));
        } catch (initError) {
            setError(getErrorMessage(initError));
            setLoading(false);

            return () => {
                unsubscribes.forEach((unsubscribe) => unsubscribe());
                host.destroy();
            };
        }

        const bootstrap = async () => {
            try {
                const contextPromise =
                    host.getContextLevel() === 'full'
                        ? host.getContext()
                        : Promise.resolve(undefined);
                const [
                    resolvedContext,
                    resolvedTheme,
                    resolvedLanguage,
                    resolvedUserId,
                    resolvedOrgId,
                    resolvedIsYateam,
                    resolvedIsOrbita,
                ] = await Promise.all([
                    contextPromise,
                    host.getTheme() as Promise<Theme>,
                    host.getLanguage() as Promise<string>,
                    host.getUserId() as Promise<string | undefined>,
                    host.getOrgId() as Promise<string | undefined>,
                    host.getIsYateam() as Promise<boolean | undefined>,
                    host.getIsOrbita() as Promise<boolean | undefined>,
                ]);

                if (cancelled) {
                    return;
                }

                setContext(resolvedContext);
                setTheme(resolvedTheme);
                setLanguage(resolvedLanguage);
                setUserId(resolvedUserId);
                setOrgId(resolvedOrgId);
                setIsYateam(resolvedIsYateam);
                setIsOrbita(resolvedIsOrbita);

                dispatchInitialValue('context.changed', resolvedContext);
                dispatchInitialValue('theme.changed', resolvedTheme);
                dispatchInitialValue('language.changed', resolvedLanguage);
                dispatchInitialValue('userId.changed', resolvedUserId);
                dispatchInitialValue('orgId.changed', resolvedOrgId);
                dispatchInitialValue('isYateam.changed', resolvedIsYateam);
                dispatchInitialValue('isOrbita.changed', resolvedIsOrbita);

                setLoading(false);
                await host.notifyReady();
            } catch (bootstrapError) {
                if (cancelled) {
                    return;
                }

                setError(getErrorMessage(bootstrapError));
                setLoading(false);
            }
        };

        bootstrap();

        return () => {
            cancelled = true;
            unsubscribes.forEach((unsubscribe) => unsubscribe());
            host.destroy();
        };
    }, [autoResize, host]);

    return {
        host,
        loading,
        error,
        theme,
        language,
        context,
        userId,
        orgId,
        isYateam,
        isOrbita,
    };
}
