import { hostApi } from '@weavix/sdk-core';
import { useEffect, useState } from 'react';

/**
 * Реактивный хук для получения айди текущей организации.
 * @returns Айди организации (например, `'org123'`), или `undefined` до получения первого события.
 * @example
 * ```tsx
 * function App() {
 *     const orgId = useOrgId();
 *     return <span>Айди организации: {orgId}</span>;
 * }
 * ```
 */
export function useOrgId(): string | undefined {
    const [orgId, setOrgId] = useState<string | undefined>(undefined);

    useEffect(() => {
        const init = async () => {
            const id = (await hostApi.getOrgId()) as string | undefined;

            setOrgId(id);
        };

        init();
    }, []);

    return orgId;
}
