import { on } from '@weavix/sdk-core';
import { useEffect, useState } from 'react';

/**
 * Reactive hook for receiving the current slot context pushed by the host.
 * @template T - Type of the context object (defaults to `unknown`)
 * @returns Current context, or `undefined` until the first event arrives from the host.
 * @example
 * ```tsx
 * interface IssueContext {
 *     key: string;
 *     summary: string;
 * }
 *
 * function App() {
 *     const context = useContext<IssueContext>();
 *     if (!context) return <Loader />;
 *     return <div>{context.summary}</div>;
 * }
 * ```
 */
export function useContext<T = unknown>(): T | undefined {
    const [context, setContext] = useState<T | undefined>(() => {
        let initial: T | undefined;
        const unsubscribe = on('context.changed', (value) => {
            initial = value as T;
        });
        unsubscribe();
        return initial;
    });

    useEffect(() => {
        const unsubscribe = on('context.changed', (value) => {
            setContext(value as T);
        });

        return unsubscribe;
    }, []);

    return context;
}
