import { on } from '@weavix/sdk-core';
import { useEffect, useState } from 'react';

/**
 * Реактивный хук для получения текущего статуса Орбиты.
 * @returns Включена ли Орбита (например, 'true'), или `undefined` до получения первого события.
 * @example
 * ```tsx
 * function App() {
 *     const isOrbita = useIsOrbita();
 *     return <span>Orbita: {String(isOrbita)}</span>;
 * }
 * ```
 */
export function useIsOrbita(): boolean | undefined {
    const [isOrbita, setIsOrbita] = useState<boolean | undefined>(() => {
        let initial: boolean | undefined;
        const unsubscribe = on('isOrbita.changed', (value) => {
            initial = value;
        });

        unsubscribe();

        return initial;
    });

    useEffect(() => {
        return on('isOrbita.changed', setIsOrbita);
    }, []);

    return isOrbita;
}
