import { type Theme, on } from '@weavix/sdk-core';
import { useEffect, useState } from 'react';

/**
 * Реактивный хук для получения текущей темы хоста.
 * @returns Текущая тема (`'light'` | `'dark'` и т.д.), или `undefined` до получения первого события.
 * @example
 * ```tsx
 * function App() {
 *     const theme = useTheme();
 *     return <div className={theme}>...</div>;
 * }
 * ```
 */
export function useTheme(): Theme | undefined {
    const [theme, setTheme] = useState<Theme | undefined>(() => {
        let initial: Theme | undefined;
        const unsubscribe = on('theme.changed', (value) => {
            initial = value;
        });
        unsubscribe();
        return initial;
    });

    useEffect(() => {
        const unsubscribe = on('theme.changed', (value) => {
            setTheme(value);
        });

        return unsubscribe;
    }, []);

    return theme;
}
