import { on } from '@weavix/sdk-core';
import { useEffect, useState } from 'react';

/**
 * Реактивный хук для получения текущего языка хоста.
 * @returns Код текущего языка (например, `'ru'`, `'en'`), или `undefined` до получения первого события.
 * @example
 * ```tsx
 * function App() {
 *     const language = useLanguage();
 *     return <span>Текущий язык: {language}</span>;
 * }
 * ```
 */
export function useLanguage(): string | undefined {
    const [language, setLanguage] = useState<string | undefined>(() => {
        let initial: string | undefined;
        const unsubscribe = on('language.changed', (value) => {
            initial = value;
        });
        unsubscribe();
        return initial;
    });

    useEffect(() => {
        const unsubscribe = on('language.changed', (value) => {
            setLanguage(value);
        });

        return unsubscribe;
    }, []);

    return language;
}
