import { type ToastOptions, uiApi } from '@weavix/sdk-core';
import { useCallback } from 'react';

export type UseToasterReturn = {
    add: (options: ToastOptions) => Promise<{ name: string }>;
};

const useToasterImpl = () => {
    const add = useCallback((options: ToastOptions) => uiApi.toaster.add(options), []);

    return { add };
};

export const useToaster = useToasterImpl as () => UseToasterReturn;
