import { hostApi } from '@weavix/sdk-core';
import { useEffect, useState } from 'react';

/**
 * Реактивный хук для получения текущей сборки приложения.
 * @returns Является ли ятимом приложение (например, 'true'), или `undefined` до получения первого события.
 * @example
 * ```tsx
 * function App() {
 *     const isYateam = useIsYateam();
 *     return <span>Ятим ли сейчас?: {isYateam}</span>;
 * }
 * ```
 */
export function useIsYateam(): boolean | undefined {
    const [isYateam, setIsYateam] = useState<boolean | undefined>(undefined);

    useEffect(() => {
        const init = async () => {
            const yateam = (await hostApi.getIsYateam()) as boolean | undefined;
            setIsYateam(yateam);
        };

        init();
    }, []);

    return isYateam;
}
